<template>
 <view class="shell">
  <view class="header row"><view class="brand"><text class="brand-icon">拾</text><text>拾光自习</text></view><text class="label">MAKE EVERY DAY COUNT</text></view>
  <view v-if="!token" class="auth">
   <view class="eyebrow">YOUR PERSONAL STUDY SPACE</view><view class="hero">把每一次坚持，<br/>变成看得见的成长。</view><view class="muted intro">一个计划，一次专注，一点进步。</view>
   <view class="card"><view class="title">{{registering?'开启学习之旅':'欢迎回来'}}</view><view class="hint gap">{{registering?'创建账号，记录属于你的学习节奏':'登录后继续今天的小目标'}}</view><input v-model="credentials.username" placeholder="用户名（3–32 个字符）" maxlength="32"/><input v-model="credentials.password" password placeholder="密码（至少 8 字节）" maxlength="72"/><button class="primary" :disabled="busy" @click="authenticate">{{busy?'正在连接…':registering?'注册并开始':'登录'}}</button><button @click="registering=!registering">{{registering?'已有账号？去登录':'还没有账号？立即注册'}}</button></view>
   <view class="card"><view class="label">后端服务地址</view><input v-model="base" placeholder="https://你的服务域名"/><button @click="saveBase">保存服务地址</button><view class="hint">手机请填写电脑局域网 IP 或 HTTPS 域名，127.0.0.1 仅用于本机预览。</view></view>
  </view>
  <view v-else>
   <view class="greeting row"><view><view class="label">{{dateLabel}}</view><view class="hero small">{{tab==='today'?'今天，也向前一步。':tab==='plans'?'让目标有迹可循。':tab==='stats'?'每份努力，都有回响。':'回看走过的每一天。'}}</view><view class="muted">你好，{{username}} · 按自己的节奏成长</view></view><text class="avatar">{{username.slice(0,1)}}</text></view>
   <view class="error" v-if="error">{{error}}<text @click="load">　点击重试</text></view>
   <view v-if="loading" class="hint">正在同步学习记录…</view>
   <view v-if="tab==='today'">
    <view class="focus"><view class="eyebrow">A LITTLE PROGRESS, EVERY DAY</view><view class="focus-title">积跬步，至千里。</view><view class="focus-text">今天完成 {{todayDone}} / {{activePlans.length}} 个学习计划</view><view class="track"><view :style="{width: todayRate+'%'}"/></view><view class="row focus-foot"><text>保持热爱，持续积累</text><text>{{todayRate}}%</text></view></view>
    <view class="metrics"><view class="card"><text class="label">累计打卡</text><view class="number">{{stats.total_checkins||0}}<text> 次</text></view></view><view class="card"><text class="label">连续学习</text><view class="number">{{stats.streak||0}}<text> 天</text></view></view></view>
    <view class="row section"><text class="title">今日学习清单</text><text class="link" @click="newPlan">＋ 新建计划</text></view>
    <view class="empty card" v-if="!activePlans.length">今天还没有进行中的计划<br/><text class="link" @click="newPlan">创建第一个学习计划 →</text></view>
    <view v-for="p in activePlans" :key="p.id" class="card plan" @click="openDetail(p)"><view class="row"><text class="plan-name">{{p.name}}</text><text class="pill">{{p.cycle==='daily'?'每日学习':'每周学习'}}</text></view><view class="muted desc">{{p.description||'每天积累一点，离目标更近一点。'}}</view><view class="row"><text class="label">已打卡 {{p.checkin_count}} / {{p.target}} 次</text><button class="compact" :class="{primary:!p.checked_today}" :disabled="p.checked_today" @click.stop="openCheckin(p)">{{p.checked_today?'✓ 今日已完成':'去打卡 →'}}</button></view></view>
   </view>
   <view v-if="tab==='plans'"><view class="row section"><text class="title">我的计划 · {{plans.length}}</text><text class="link" @click="newPlan">＋ 新建</text></view><view class="empty card" v-if="!plans.length">还没有计划，点击右上角新建。</view><view v-for="p in plans" :key="p.id" class="card" @click="openDetail(p)"><view class="row"><text class="title">{{p.name}}</text><text class="pill">{{status(p)}}</text></view><view class="muted desc">{{p.description||'暂无描述'}}</view><view class="label">{{p.start_date}} 至 {{p.end_date}}</view><view class="progress"><view :style="{width:rate(p)+'%'}"/></view><view class="row"><text class="label">{{p.checkin_count}} / {{p.target}} 次 · {{p.cycle==='daily'?'每日':'每周'}}</text><text class="link">查看详情 →</text></view></view></view>
   <view v-if="tab==='stats'"><view class="metrics"><view class="card"><text class="label">总学习时间</text><view class="number">{{stats.total_minutes||0}}<text> 分</text></view></view><view class="card"><text class="label">计划完成率</text><view class="number">{{Math.round((stats.completion_rate||0)*100)}}<text> %</text></view></view></view><view class="card"><view class="title">学习趋势</view><view class="hint">最近 30 天 · 每日打卡次数</view><scroll-view scroll-x class="chart-scroll"><view class="bars"><view v-for="d in stats.trend||[]" :key="d.day" class="bar-item"><text class="bar-number">{{d.count||''}}</text><view class="bar" :style="{height:Math.max(3,d.count/maxTrend*170)+'rpx',background:d.count?'#7771eb':'#eeedf8'}"/><text class="bar-label">{{d.day.slice(5)}}</text></view></view></scroll-view></view><view class="card"><view class="title">计划完成情况</view><view v-if="!plans.length" class="empty">创建计划后，在这里查看成长轨迹。</view><view v-for="p in stats.plans||[]" :key="p.id" class="gap"><view class="row"><text>{{p.name}}</text><text class="label">{{p.count}} / {{p.target}} 次</text></view><view class="progress"><view :style="{width:Math.round(p.rate*100)+'%'}"/></view></view></view><view class="hint">完成率 = 达到目标次数的计划数 / 全部计划数。连续学习按北京时间计算；当天未打卡时允许从昨天延续。</view></view>
   <view v-if="tab==='history'"><view class="row section"><text class="title">学习足迹</text><text class="label">最近 500 条</text></view><view v-if="!history.length" class="empty card">还没有打卡记录，今天就开始吧。</view><view v-for="c in history" :key="c.id" class="card"><view class="row"><text class="title">{{c.plan_name}}</text><text class="pill">{{c.minutes}} 分钟</text></view><view class="muted desc">{{c.note||'今天又积累了一点进步。'}}</view><text class="label">{{c.day}} · 已完成打卡</text></view></view>
   <view class="account row"><text @click="settings=true">⚙ 服务设置</text><text @click="logout">退出登录</text></view>
   <view class="bottom"><view v-for="item in tabs" :key="item.key" :class="['nav-item',{selected:tab===item.key}]" @click="tab=item.key"><text class="nav-symbol">{{item.icon}}</text><text>{{item.label}}</text></view></view>
  </view>
  <view v-if="modal" class="overlay"><scroll-view scroll-y class="dialog"><view class="row"><text class="title">{{modal==='plan'?(form.id?'编辑学习计划':'新建学习计划'):modal==='checkin'?'记录今天的努力':'计划详情'}}</text><text class="close" @click="modal=''">×</text></view>
   <view v-if="modal==='plan'"><view class="label gap">计划名称</view><input v-model="form.name" maxlength="100" placeholder="例如：每天阅读 30 分钟"/><view class="label">学习描述</view><textarea v-model="form.description" maxlength="2000" placeholder="写下你的学习内容与期待"/><view class="row"><text>学习周期</text><picker :range="['每日','每周']" :value="form.cycle==='daily'?0:1" @change="form.cycle=Number($event.detail.value)===0?'daily':'weekly'"><text class="pill">{{form.cycle==='daily'?'每日':'每周'}} ▾</text></picker></view><view class="label gap">整个计划目标打卡次数（每日每计划最多一次）</view><input v-model.number="form.target" type="number" placeholder="目标次数"/><view class="row gap"><text>开始日期</text><picker mode="date" :value="form.start_date" @change="form.start_date=$event.detail.value"><text class="pill">{{form.start_date}} ▾</text></picker></view><view class="row gap"><text>结束日期</text><picker mode="date" :value="form.end_date" @change="form.end_date=$event.detail.value"><text class="pill">{{form.end_date}} ▾</text></picker></view><button class="primary gap" :disabled="busy" @click="savePlan">保存计划</button></view>
   <view v-if="modal==='checkin'"><view class="muted gap">{{selected.name}} · {{localDay()}}</view><view class="label gap">学习时长（分钟）</view><input v-model.number="checkform.minutes" type="number"/><textarea v-model="checkform.note" maxlength="1000" placeholder="今天学到了什么？记录一点心得…"/><button class="primary" :disabled="busy" @click="submitCheckin">完成今日打卡 ✓</button></view>
   <view v-if="modal==='detail'"><view class="hero small">{{selected.name}}</view><view class="muted desc">{{selected.description||'暂无描述'}}</view><view class="pill">{{status(selected)}}</view><view class="hint gap">周期：{{selected.cycle==='daily'?'每日':'每周'}}<br/>时间：{{selected.start_date}} 至 {{selected.end_date}}<br/>进度：{{selected.checkin_count}} / {{selected.target}} 次</view><view class="progress"><view :style="{width:rate(selected)+'%'}"/></view><button v-if="!selected.checked_today&&status(selected)==='进行中'" class="primary" @click="openCheckin(selected)">去打卡</button><button @click="editPlan">编辑计划</button><button class="danger" :disabled="busy" @click="deletePlan">删除计划</button><view class="title gap">打卡记录</view><view v-if="!detailHistory.length" class="empty">暂无打卡记录</view><view v-for="c in detailHistory" :key="c.id" class="detail-record"><view class="row"><text>{{c.day}}</text><text class="pill">{{c.minutes}} 分钟</text></view><view class="hint">{{c.note||'完成一次学习'}}</view></view></view>
  </scroll-view></view>
  <view v-if="settings" class="overlay"><view class="dialog"><view class="row"><text class="title">服务设置</text><text class="close" @click="settings=false">×</text></view><input v-model="base"/><button class="primary" @click="saveBase">保存（切换服务后重新登录）</button></view></view>
 </view>
</template>
<script>
import { request,getBase,setBase } from '../../common/api'
export default {
 data(){return {token:uni.getStorageSync('token')||'',username:uni.getStorageSync('username')||'学习者',base:getBase(),credentials:{username:'',password:''},registering:false,busy:false,loading:false,error:'',tab:'today',plans:[],history:[],stats:{},modal:'',settings:false,selected:{},detailHistory:[],form:{},checkform:{minutes:30,note:''},tabs:[{key:'today',label:'今日',icon:'◷'},{key:'plans',label:'计划',icon:'▤'},{key:'stats',label:'统计',icon:'▥'},{key:'history',label:'足迹',icon:'◴'}] }},
 computed:{dateLabel(){return this.localDay()+' · 学习的好日子'},activePlans(){const d=this.localDay();return this.plans.filter(p=>p.start_date<=d&&p.end_date>=d)},todayDone(){return this.activePlans.filter(p=>p.checked_today).length},todayRate(){return this.activePlans.length?Math.round(this.todayDone/this.activePlans.length*100):0},maxTrend(){return Math.max(1,...(this.stats.trend||[]).map(d=>d.count))}},
 onLoad(){uni.$on('session-expired',this.expire);if(this.token)this.load()},onShow(){if(this.token)this.load()},onUnload(){uni.$off('session-expired',this.expire)},onPullDownRefresh(){this.load().finally(()=>uni.stopPullDownRefresh())},
 methods:{
 localDay(){return new Date(Date.now()+8*3600000).toISOString().slice(0,10)},toast(e){uni.showToast({title:e.message||e,icon:'none',duration:3000})},expire(){this.token='';this.plans=[];this.history=[];this.stats={};this.modal=''},
 async authenticate(){if(this.busy)return;this.busy=true;try{const r=await request(this.registering?'/register':'/login','POST',this.credentials);uni.setStorageSync('token',r.token);uni.setStorageSync('username',r.username);this.token=r.token;this.username=r.username;this.credentials.password='';await this.load()}catch(e){this.toast(e)}finally{this.busy=false}},
 async load(){if(!this.token||this.loading)return;this.loading=true;this.error='';try{const [p,s,h]=await Promise.all([request('/plans'),request('/stats'),request('/checkins')]);this.plans=p;this.stats=s;this.history=h}catch(e){this.error=e.message}finally{this.loading=false}},
 saveBase(){try{const changed=getBase()!==this.base.trim().replace(/\/+$/,'');setBase(this.base);this.settings=false;if(changed){uni.removeStorageSync('token');this.expire()}this.toast('服务地址已保存')}catch(e){this.toast(e)}},
 async logout(){if(this.busy)return;try{await request('/logout','POST');uni.removeStorageSync('token');this.expire()}catch(e){this.toast(e)}},
 rate(p){return Math.min(100,Math.round(p.checkin_count/p.target*100))},status(p){const d=this.localDay();return p.start_date>d?'未开始':p.end_date<d?'已结束':'进行中'},
 newPlan(){this.form={name:'',description:'',cycle:'daily',target:30,start_date:this.localDay(),end_date:new Date(Date.now()+29*86400000+8*3600000).toISOString().slice(0,10)};this.modal='plan'},
 async openDetail(p){this.selected=p;this.detailHistory=[];this.modal='detail';try{this.detailHistory=await request('/checkins?plan_id='+p.id)}catch(e){this.toast(e)}},editPlan(){this.form={...this.selected};this.modal='plan'},
 async savePlan(){if(this.busy)return;if(!this.form.name.trim()||!Number.isInteger(Number(this.form.target))||Number(this.form.target)<1||this.form.start_date>this.form.end_date){this.toast('请填写名称、正整数目标和有效日期');return}this.busy=true;try{const {name,description,cycle,target,start_date,end_date}=this.form;await request('/plans'+(this.form.id?'/'+this.form.id:''),this.form.id?'PUT':'POST',{name,description,cycle,target:Number(target),start_date,end_date});this.modal='';await this.load();this.toast('计划已保存')}catch(e){this.toast(e)}finally{this.busy=false}},
 deletePlan(){uni.showModal({title:'删除学习计划',content:'将同时删除该计划全部打卡记录，无法恢复。',success:async r=>{if(!r.confirm||this.busy)return;this.busy=true;try{await request('/plans/'+this.selected.id,'DELETE');this.modal='';await this.load()}catch(e){this.toast(e)}finally{this.busy=false}}})},
 openCheckin(p){this.selected=p;this.checkform={minutes:30,note:''};this.modal='checkin'},async submitCheckin(){if(this.busy)return;this.busy=true;try{await request('/checkins','POST',{plan_id:this.selected.id,minutes:Number(this.checkform.minutes),note:this.checkform.note});this.modal='';await this.load();this.toast('打卡成功，今天又进步了一点！')}catch(e){this.toast(e)}finally{this.busy=false}}
 }
}
</script>
<style scoped>
.shell{max-width:1000rpx;margin:auto;padding:0 36rpx 180rpx}.header{padding-top:calc(var(--status-bar-height) + 34rpx);padding-bottom:36rpx;border-bottom:1rpx solid #e9ebf2}.brand{display:flex;align-items:center;font-weight:700;font-size:32rpx;gap:16rpx}.brand-icon{background:#6963e7;color:#fff;padding:9rpx 14rpx;border-radius:14rpx}.header .label{font-size:16rpx;letter-spacing:2rpx}.auth{padding-top:70rpx}.eyebrow{font-size:18rpx;letter-spacing:3rpx;color:#8d87c4}.hero{font-size:54rpx;font-weight:750;line-height:1.5;margin:24rpx 0}.hero.small{font-size:40rpx;margin:14rpx 0 18rpx}.intro{margin-bottom:50rpx}.greeting{padding:42rpx 0}.avatar{height:78rpx;width:78rpx;border-radius:50%;background:#e7e3ff;color:#7163d8;display:flex;align-items:center;justify-content:center;font-size:32rpx}.focus{padding:38rpx;border-radius:30rpx;background:#6661db;color:white;margin-bottom:26rpx}.focus .eyebrow{color:#d8d5ff}.focus-title{font-size:44rpx;font-weight:700;margin:28rpx 0 16rpx}.focus-text{color:#e9e8ff;font-size:25rpx}.track{background:#ffffff30;height:10rpx;border-radius:10rpx;margin:36rpx 0 18rpx;overflow:hidden}.track view{background:#d8f3c7;height:100%}.focus-foot{font-size:20rpx;color:#dedcff}.metrics{display:flex;gap:22rpx}.metrics .card{flex:1}.number{font-size:48rpx;font-weight:700;margin-top:20rpx}.number text{font-size:22rpx;color:#9da1b2;font-weight:400}.section{margin:20rpx 0 28rpx}.link{color:#7569db;font-size:24rpx}.plan-name{font-size:31rpx;font-weight:600}.desc{font-size:25rpx;line-height:1.8;margin:22rpx 0 28rpx;word-break:break-all}.compact{font-size:23rpx;padding:0 24rpx;line-height:64rpx;margin:0}.progress{height:12rpx;background:#eeedf9;border-radius:12rpx;overflow:hidden;margin:26rpx 0}.progress view{height:100%;background:#8c83ee;border-radius:12rpx}.account{font-size:23rpx;color:#9a9dae;margin:44rpx 0}.bottom{position:fixed;bottom:0;left:0;right:0;background:#ffffffed;border-top:1rpx solid #edecf4;padding:18rpx 24rpx calc(18rpx + env(safe-area-inset-bottom));display:flex;justify-content:space-around;z-index:5}.nav-item{display:flex;flex-direction:column;align-items:center;gap:8rpx;font-size:21rpx;color:#aaaebd;min-width:100rpx}.nav-symbol{font-size:40rpx;line-height:46rpx}.selected{color:#6a60d8}.overlay{position:fixed;inset:0;z-index:20;background:#17152c80;display:flex;align-items:center;justify-content:center;padding:30rpx}.dialog{background:#fff;width:100%;max-width:850rpx;max-height:85vh;padding:36rpx;border-radius:30rpx}.close{font-size:46rpx;color:#9d9bad;padding:0 15rpx}.chart-scroll{width:100%;margin-top:35rpx}.bars{display:flex;align-items:flex-end;height:250rpx;min-width:1500rpx;padding:10rpx 0 25rpx}.bar-item{width:50rpx;flex-shrink:0;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:230rpx}.bar{width:24rpx;border-radius:6rpx}.bar-label{font-size:14rpx;color:#a2a2b3;margin-top:12rpx;white-space:nowrap}.bar-number{font-size:17rpx;color:#8b81de;height:25rpx}.error{background:#fff0f1;color:#c85468;padding:24rpx;border-radius:16rpx;margin-bottom:25rpx;font-size:24rpx}.detail-record{border-top:1rpx solid #eee;padding:24rpx 0}
</style>
